use crate::finite_continuation::{ContinuationError, PartialDynamics};
use crate::finite_independence::{SwapCertificate, SwapOutcome};
use std::collections::{BTreeSet, VecDeque};
use std::rc::Rc;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ReplayMode {
    ExactState,
    ProtectedFutures,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TraceLimits {
    pub max_words: usize,
    pub max_word_len: usize,
    pub max_swap_checks: usize,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TraceLink {
    pub from: Vec<usize>,
    pub position: usize,
    pub swap: SwapCertificate,
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TraceComponent {
    pub start: usize,
    pub word: Vec<usize>,
    pub mode: ReplayMode,
    /// Sorted complete component; first entry is its canonical representative.
    pub members: Vec<Vec<usize>>,
    /// Discovery tree, retaining the actual witnesses that generate the class.
    pub tree: Vec<TraceLink>,
}

struct TraceFrontier {
    seen: BTreeSet<Rc<Vec<usize>>>,
    queue: VecDeque<Rc<Vec<usize>>>,
    tree: Vec<TraceLink>,
    checks: usize,
}

impl TraceFrontier {
    fn new(word: &[usize]) -> Self {
        let initial = Rc::new(word.to_vec());
        Self {
            seen: BTreeSet::from([Rc::clone(&initial)]),
            queue: VecDeque::from([initial]),
            tree: Vec::new(),
            checks: 0,
        }
    }

    fn charge(&mut self, limit: usize) -> Result<(), ContinuationError> {
        if self.checks >= limit {
            return Err(ContinuationError::WorkLimit);
        }
        self.checks += 1;
        Ok(())
    }

    fn register(
        &mut self,
        next: &Vec<usize>,
        from: &[usize],
        position: usize,
        swap: SwapCertificate,
        max_words: usize,
    ) -> Result<(), ContinuationError> {
        if !self.seen.contains(next) {
            if self.seen.len() >= max_words {
                return Err(ContinuationError::WorkLimit);
            }
            let next = Rc::new(next.clone());
            self.seen.insert(Rc::clone(&next));
            self.queue.push_back(next);
            self.tree.push(TraceLink {
                from: from.to_vec(),
                position,
                swap,
            });
        }
        Ok(())
    }
}

fn trace_admission(
    machine: &PartialDynamics,
    start: usize,
    word: &[usize],
    limits: TraceLimits,
) -> Result<usize, ContinuationError> {
    if word.len() > limits.max_word_len || limits.max_words == 0 {
        return Err(ContinuationError::WorkLimit);
    }
    if machine.run(start, word)?.is_none() {
        return Err(ContinuationError::CertificateMismatch);
    }
    machine
        .reports()
        .len()
        .checked_add(1)
        .and_then(|n| n.checked_mul(n))
        .ok_or(ContinuationError::WorkLimit)
}

fn admissible_swap(
    machine: &PartialDynamics,
    start: usize,
    word: &[usize],
    position: usize,
    mode: ReplayMode,
    pairs: usize,
) -> Result<Option<SwapCertificate>, ContinuationError> {
    let s = machine
        .run(start, &word[..position])?
        .ok_or(ContinuationError::CertificateMismatch)?;
    let swap = machine.certify_swap(s, word[position], word[position + 1], pairs)?;
    let SwapOutcome::Independent { ab, ba } = swap.outcome else {
        return Ok(None);
    };
    if mode == ReplayMode::ExactState && ab != ba {
        return Ok(None);
    }
    Ok(Some(swap))
}

fn expand_word(
    machine: &PartialDynamics,
    start: usize,
    word: &[usize],
    mode: ReplayMode,
    pairs: usize,
    limits: TraceLimits,
    frontier: &mut TraceFrontier,
) -> Result<(), ContinuationError> {
    let mut scratch = None;
    for position in 0..word.len().saturating_sub(1) {
        frontier.charge(limits.max_swap_checks)?;
        let Some(swap) = admissible_swap(machine, start, word, position, mode, pairs)? else {
            continue;
        };
        if word[position] == word[position + 1] {
            continue;
        }
        // One reusable scratch word per expansion; queue and seen share each
        // newly discovered word. Public owned tree/member outputs stay exact.
        let next = scratch.get_or_insert_with(|| word.to_vec());
        next.swap(position, position + 1);
        frontier.register(next, word, position, swap, limits.max_words)?;
        next.swap(position, position + 1);
    }
    Ok(())
}

impl PartialDynamics {
    pub fn trace_component(
        &self,
        start: usize,
        word: &[usize],
        mode: ReplayMode,
        limits: TraceLimits,
    ) -> Result<TraceComponent, ContinuationError> {
        let pairs = trace_admission(self, start, word, limits)?;
        let mut frontier = TraceFrontier::new(word);
        while let Some(word) = frontier.queue.pop_front() {
            expand_word(self, start, &word, mode, pairs, limits, &mut frontier)?;
        }
        Ok(TraceComponent {
            start,
            word: word.to_vec(),
            mode,
            members: frontier.seen.into_iter().map(Rc::unwrap_or_clone).collect(),
            tree: frontier.tree,
        })
    }
    // Sorted complete component; first entry is its canonical representative.
    // Discovery tree, retaining the actual witnesses that generate the class.
    // Recompute closure, not just the submitted edges. Removing a member or
    // substituting another start/mode/word cannot certify an incomplete class.
    /// Recompute closure, not just the submitted edges. Removing a member or
    /// substituting another start/mode/word cannot certify an incomplete class.
    pub fn verify_trace(
        &self,
        start: usize,
        word: &[usize],
        mode: ReplayMode,
        limits: TraceLimits,
        certificate: &TraceComponent,
    ) -> Result<(), ContinuationError> {
        if self.trace_component(start, word, mode, limits)? == *certificate {
            Ok(())
        } else {
            Err(ContinuationError::CertificateMismatch)
        }
    }
}

